SELECT sku_scanned, count(DISTINCT unit_price) AS n_prices, min(unit_price) AS min_p, max(unit_price) AS max_p,
       count(*) FILTER (WHERE unit_price <> (SELECT p.price_inr FROM store.products p WHERE p.sku = pos_lines.sku_scanned)) AS lines_off_list
FROM store.pos_lines GROUP BY 1 ORDER BY 1;

SELECT sku, count(*) AS audits, count(*) FILTER (WHERE status='empty') AS empties,
       min(audit_ts)::date AS first_audit, max(audit_ts)::date AS last_audit
FROM store.shelf_audits GROUP BY sku ORDER BY sku;

SELECT sku, sum(units) AS units, count(*) AS rows, string_agg(DISTINCT reason, ',') AS reasons
FROM store.store_orders WHERE created_ts >= DATE '2026-06-01' AND created_ts < DATE '2026-07-01'
GROUP BY sku ORDER BY units DESC;
